
const S={data:null,student:'liam',subject:'biology',chapter:1,view:'home',tab:'learn'};
const PROGRESS_KEY='devries-learning-progress',LEGACY_PROGRESS_KEY='liam-progress',PROGRESS_SCHEMA_VERSION=3,STUDENTS={liam:{id:'liam',name:'Liam DeVries',grade:9},leilani:{id:'leilani',name:'Leilani DeVries',grade:11}};
