if(meta.conceptId==='cell-structure-function')return {...base,title:'Try It: Match Structure to Job',scenario:`A cell diagram in ${section} shows several parts that each do a job.`,question:'Which answer best uses structure-function thinking?',choices:[`${t.term} matters because its structure helps it do a specific job in the cell.`,`Cell parts do not have jobs.`,`Every cell part does the exact same thing.`],answer:`Explain ${t.term} by connecting the structure to what it does.`,steps:['Cell part','Structure clue','Function','Why it matters'],apply:`Describe the job of ${t.term} and how it helps the cell.`}
if(meta.conceptId==='cell-transport')return {...base,title:'Try It: Predict Movement Across a Membrane',scenario:`A membrane separates two areas with different concentrations during ${section}.`,question:'What should you consider before predicting movement?',choices:['The concentration difference and whether the transport uses energy.','Only the color of the picture.','Whether the word is long or short.'],answer:'Use concentration, membrane, diffusion, osmosis, passive transport, or active transport as taught in the section.',steps:['Membrane','Concentration difference','Movement','Energy?'],apply:'Predict the direction of movement in one membrane example and explain why.'}
if(meta.conceptId==='cell-energy-process')return {...base,title:'Try It: Sequence the Energy Process',scenario:`The section ${section} explains a process that changes matter and energy in cells.`,question:'Which reasoning matches the lesson?',choices:['Name the inputs, follow the process, and identify the outputs.','Skip the inputs and guess the output.','Assume all cell energy processes are identical.'],answer:'Use the process order and the correct inputs and outputs from the section.',steps:['Inputs','Process steps','Outputs','Cell use'],apply:'Name one input and one output from this section’s energy process.'}
if(meta.conceptId==='cell-division-sequence')return {...base,title:'Try It: Put the Cell Event in Order',scenario:`A cell must complete the events described in ${section} in a workable order.`,question:'What kind of evidence helps you sequence it?',choices:['Chromosome position, copying, separation, and the result for new cells.','The color of the textbook heading.','Only the final picture, with no steps.'],answer:'Use the sequence of cell-cycle, mitosis, or meiosis events from the section.',steps:['Start state','Copy/line up','Separate','Result'],apply:'Write two events from the section in the correct order and explain why that order matters.'}
if(meta.conceptId==='genetic-information')return {...base,title:'Try It: Use Genetic Instructions',scenario:`In ${section}, genetic information affects a trait or cell process.`,question:'Which answer uses genetic reasoning?',choices:['DNA or genes provide instructions that can affect proteins, traits, or inheritance.','Genes are random decorations inside cells.','Traits never connect to inherited information.'],answer:'Use DNA, gene, chromosome, protein, mutation, or heredity accurately.',steps:['Genetic information','Instruction/change','Trait or protein','Evidence'],apply:`Explain how ${t.term} connects to a trait, protein, or inherited pattern.`}
if(meta.conceptId==='evolution-evidence')return {...base,title:'Try It: Compare Evolution Evidence',scenario:`A population in ${section} shows variation and some traits help survival or reproduction.`,question:'Which explanation uses evidence correctly?',choices:['Traits that improve survival or reproduction can become more common over generations.','An individual chooses to evolve instantly.','All variation disappears before selection can happen.'],answer:'Use adaptation, variation, natural selection, fossil evidence, or classification evidence from the section.',steps:['Variation','Environment','Survival/reproduction','Change over time'],apply:'Use one piece of evidence from the section to explain an evolutionary change.'}
if(meta.conceptId==='location-coordinates')return {...base,title:'Try It: Read the Location',scenario:`A map in ${section} gives a place using latitude and longitude coordinates.`,question:'What kind of location uses coordinates?',choices:['Absolute location, because coordinates identify an exact position.','Relative location, because it only compares nearby landmarks.','A region, because coordinates always describe culture.'],answer:'Latitude and longitude give absolute location.',steps:['Latitude','Longitude','Exact point','Explain'],apply:'Give one absolute-location clue and one relative-location clue for the same place.'}
