// Reusable academic PDF renderer for worksheets, reports, portfolios, and semester exports.
function pdfClean(value){return String(value??'').normalize('NFKD').replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/[\u2013\u2014]/g,'-').replace(/\u2192/g,'->').replace(/\u2022/g,'-').replace(/\u2713/g,'Completed').replace(/\u00A0/g,' ').replace(/[^\x09\x0A\x0D\x20-\x7E]/g,'')}
function pdfHex(value){let s=pdfClean(value),hex='';for(let ch of s)hex+=ch.charCodeAt(0).toString(16).toUpperCase().padStart(2,'0');return `<${hex}>`}
function pdfLineWidth(size){return Math.max(38,Math.floor(490/(size*.48)))}
function pdfWrap(text,size=10,maxChars=0){let out=[];String(text??'').split(/\n/).forEach(line=>{line=pdfClean(line).replace(/\s+/g,' ').trim();if(!line){out.push('');return}let limit=maxChars||pdfLineWidth(size);while(line.length>limit){let cut=line.lastIndexOf(' ',limit);if(cut<24)cut=limit;out.push(line.slice(0,cut).trim());line=line.slice(cut).trim()}out.push(line)});return out}
function pdfTextCmd(x,y,text,size=10,font='F1',gray=0){return `BT ${gray} g /${font} ${size} Tf ${x} ${y} Td ${pdfHex(text)} Tj ET\n`}
function pdfMathTextCmd(x,y,text,size=10,font='F1',gray=0){let source=pdfClean(text),parts=[],last=0,re=/\^\(?(-?\d+|[a-z])\)?/gi,m;while((m=re.exec(source))){if(m.index>last)parts.push({text:source.slice(last,m.index),sup:false});parts.push({text:m[1],sup:true});last=re.lastIndex}if(last<source.length)parts.push({text:source.slice(last),sup:false});if(!parts.some(p=>p.sup))return pdfTextCmd(x,y,source,size,font,gray);let body=`BT ${gray} g /${font} ${size} Tf ${x} ${y} Td `;for(let part of parts){if(part.sup)body+=`3 Ts /${font} ${Math.max(6,size*.7)} Tf ${pdfHex(part.text)} Tj 0 Ts /${font} ${size} Tf `;else body+=`${pdfHex(part.text)} Tj `}return body+'ET\n'}
function pdfNumber(value){let s=String(value||'').trim();if(s.includes('/')){let [a,b]=s.split('/').map(Number);return b?a/b:Number(a)}return Number(s)}
function inequalityGraphSpec(answer){let s=pdfClean(answer).toLowerCase().split(/[.;]/)[0].replace(/\s+/g,' '),segments=[],between=s.match(/(-?\d+(?:\/\d+)?)\s*(<=|<)\s*[a-z]\s*(<=|<)\s*(-?\d+(?:\/\d+)?)/i);if(between)segments.push({lo:pdfNumber(between[1]),hi:pdfNumber(between[4]),loClosed:between[2]==='<=',hiClosed:between[3]==='<='});if(!between)for(let m of s.matchAll(/([a-z])\s*(<=|>=|<|>)\s*(-?\d+(?:\/\d+)?)/gi)){let n=pdfNumber(m[3]),op=m[2];segments.push(op.includes('<')?{lo:-Infinity,hi:n,hiClosed:op==='<=',loClosed:false}:{lo:n,hi:Infinity,loClosed:op==='>=',hiClosed:false})}return {segments,endpoints:segments.flatMap(seg=>[seg.lo,seg.hi]).filter(Number.isFinite)}}
