function backupPayload(){return {student:currentStudent(),schemaVersion:PROGRESS_SCHEMA_VERSION,exportedAt:new Date().toISOString(),app:'DeVries Learning',progress:saved}}
function exportProgressBackup(){save();let blob=new Blob([JSON.stringify(backupPayload(),null,2)],{type:'application/json'});download(blob,`${studentFileName()}_Learning_Backup_${new Date().toISOString().slice(0,10)}.json`)}
